/**
 * Typed access to the tuning constants exported from the Python game.
 *
 * `data/config.json` is generated by `tools/export_data.py` and is the single
 * source of truth for balance. Nothing here invents a number: if a constant is
 * missing from the export that is a bug in the exporter, and `assertConfig()`
 * says so loudly at boot rather than letting a silent default change the feel
 * of the game.
 */

import raw from "../data/config.json";

type RawConfig = Record<string, unknown>;
const C = (raw as { config: RawConfig }).config;

const missing: string[] = [];

function num(key: string, fallback: number): number {
  const v = C[key];
  if (typeof v === "number" && Number.isFinite(v)) return v;
  missing.push(key);
  return fallback;
}

function int(key: string, fallback: number): number {
  return Math.round(num(key, fallback));
}

function bool(key: string, fallback: boolean): boolean {
  const v = C[key];
  if (typeof v === "boolean") return v;
  missing.push(key);
  return fallback;
}

function str(key: string, fallback: string): string {
  const v = C[key];
  if (typeof v === "string") return v;
  missing.push(key);
  return fallback;
}

