/**
 * Steering. Turn radius is speed/omega, so a constant angular rate makes the
 * snake turn wider the faster it moves. Holding the *radius* constant and
 * deriving omega from speed is what keeps a hairpin at 40-76 px at every
 * speed in the game. See the note in snake/config.py for the measurements.
 */
export const SNAKE_MIN_TURN_RADIUS = num("SNAKE_MIN_TURN_RADIUS", 20);
