// ---------------------------------------------------------------------------
// Touch / responsive additions (web only - no Python counterpart)
// ---------------------------------------------------------------------------
/**
 * Physical-size driven, from the touch study: on a phone the snake is ~2.3 mm
 * wide and a hand covers ~72% of the arena's height, versus ~36% on a tablet.
 * That 2x occlusion gap is why phone and tablet get different schemes.
 */
export const TOUCH_STEER_DEADZONE_PX = 12;   // CSS px before a drag steers
export const TOUCH_ANCHOR_RECENTRE = 60;     // CSS px/s the anchor chases the finger
export const TOUCH_AIM_DISTANCE = 400;       // canvas px projected ahead of the head
export const TOUCH_TABLET_OFFSET = 85;       // canvas px aim offset on tablets
export const TOUCH_MIN_TARGET_PX = 44;       // minimum hit target, CSS px
export const TABLET_MIN_MIN_EDGE_PX = 600;   // >= this short edge counts as a tablet

/** Report any constant the export failed to provide. */
export function configProblems(): string[] {
  return [...new Set(missing)];
}

export function assertConfig(): void {
  const bad = configProblems();
  if (bad.length) {
    console.error(
      `[config] ${bad.length} constant(s) missing from data/config.json, ` +
        `using fallbacks: ${bad.join(", ")}. Re-run tools/export_data.py.`,
    );
  }
}
